const { withAppBuildGradle } = require('@expo/config-plugins')

/**
 * Sign release builds with a real keystore instead of the debug one.
 *
 * `android/` is generated by `expo prebuild` and is not in the repository, so
 * there is nowhere to commit a signing config — it has to be re-applied every
 * time the directory is regenerated. That is what a config plugin is for.
 *
 * Without this, the template points the *release* build type at the *debug*
 * signing config. Expo's own comment there says to generate your own keystore.
 * Nobody did, and the consequence is not "a less trusted build": the release
 * workflow strips the debug signature and publishes an unsigned APK, which
 * Android's installer refuses outright. The download link on the releases page
 * has never been installable.
 *
 * Secrets are read from the environment *by Gradle at build time*, never
 * written into the generated file. A password baked into `build.gradle` would
 * sit in the CI workspace and in any local prebuild, which is how a signing key
 * ends up somewhere nobody remembers putting it.
 *
 * With no keystore in the environment the build is left exactly as prebuild
 * made it — debug-signed, installable, and obviously not a release. The release
 * workflow refuses to publish that; see `.github/workflows/release.yml`.
 */

const RELEASE_SIGNING_CONFIG = `        release {
            storeFile file(System.getenv("LUME_ANDROID_KEYSTORE"))
            storePassword System.getenv("LUME_ANDROID_KEYSTORE_PASSWORD")
            keyAlias System.getenv("LUME_ANDROID_KEY_ALIAS")
            keyPassword System.getenv("LUME_ANDROID_KEY_PASSWORD")
        }
`

const SIGNING_CONFIGS_OPEN = 'signingConfigs {\n'
const DEBUG_SIGNING_REFERENCE = 'signingConfig signingConfigs.debug'

/**
 * The whole transform, as a pure function, so it can be tested without running
 * a prebuild — see `plugins/with-release-signing.test.mjs`. A signing config
 * that is only exercised by a twenty-minute release build is one whose failure
 * you find out about from the release page.
 */
function applyReleaseSigning(gradle) {
  {
    // Both edits are anchored on text this plugin verified against a generated
    // file. If Expo changes the template the anchors stop matching, and the
    // build must fail here rather than quietly produce a debug-signed release —
    // a silent fallback is the exact failure this plugin exists to remove.
    if (!gradle.includes(SIGNING_CONFIGS_OPEN)) {
      throw new Error(
        'with-release-signing: no `signingConfigs {` block in android/app/build.gradle. ' +
          'The Expo template changed; update this plugin rather than skipping signing.'
      )
    }

    const references = gradle.split(DEBUG_SIGNING_REFERENCE).length - 1
    if (references !== 2) {
      throw new Error(
        `with-release-signing: expected 2 references to \`${DEBUG_SIGNING_REFERENCE}\` ` +
          `(one for debug, one the release build type wrongly inherits), found ${references}. ` +
          'The Expo template changed; update this plugin rather than skipping signing.'
      )
    }

    let patched = gradle.replace(SIGNING_CONFIGS_OPEN, SIGNING_CONFIGS_OPEN + RELEASE_SIGNING_CONFIG)

    // Only the second reference — the first belongs to the debug build type and
    // is correct as it stands.
    let seen = 0
    patched = patched.replace(new RegExp(DEBUG_SIGNING_REFERENCE, 'g'), (match) => {
      seen += 1
      return seen === 2 ? 'signingConfig signingConfigs.release' : match
    })

    return patched
  }
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (!process.env.LUME_ANDROID_KEYSTORE) return cfg
    cfg.modResults.contents = applyReleaseSigning(cfg.modResults.contents)
    return cfg
  })
}

module.exports.applyReleaseSigning = applyReleaseSigning
